/**
 * The canonical-schema pin — the first cross-runtime byte agreement on
 * the schema plane itself.
 *
 * `library/cas/schemas/*.json` are generated by executing the Lean
 * self-codec (`lake exe schemas`): each file's bytes ARE the
 * schema-node payload (`{"revision":1,"value":<representation>}` under
 * the canonical compact rendering) of one registered code. This suite
 * mirrors every registered code through native Effect Schemas
 * and asserts `CanonicalSchema.payloadOf` answers the same bytes —
 * closing the pin the implementation plan held open ("asserting the
 * schema bytes agree across runtimes is BLOCKED on the schema
 * commission's Lean Ast codec").
 *
 * Per the ratified harness rulings: the TS codes hand-mirror the Lean
 * registry (the drift tripwire), nothing here writes or repairs a
 * fixture, and a missing fixture is a red suite. The mirrors themselves
 * live in `test/fixtures/schemaRegistry.ts`, shared with the
 * materialization gate so a mirror is written once.
 */
import { expect, it } from "@effect/vitest"
import { Effect, Layer, Option } from "effect"
import { Cas } from "../src/index.ts"
import { layerDiskFs } from "./fixtures/diskFs.ts"
import { readFixtureBytes, readFixtureString } from "./fixtures/read.ts"
import { registry } from "./fixtures/schemaRegistry.ts"

const { CanonicalSchema, ConformanceVector, layerMemoryLive } = Cas

const fixtureBytes = (name: string) =>
  readFixtureBytes(`../cas/schemas/${name}.json`).pipe(Effect.orDie)

it.effect("every registered code's payload bytes agree across runtimes", () =>
  Effect.gen(function* () {
    for (const [name, ast] of registry) {
      const expected = yield* fixtureBytes(name)
      const actual = CanonicalSchema.payloadOf(ast)
      expect(`${name} ${Buffer.from(actual).toString("utf8")}`)
        .toBe(`${name} ${Buffer.from(expected).toString("utf8")}`)
    }
  }).pipe(Effect.provide(layerDiskFs)))

it.effect("the schema-node vector's payload IS payloadOf(vectorSchema)", () =>
  Effect.gen(function* () {
    const vector = JSON.parse(
      yield* readFixtureString("../cas/vectors/schema-vector-document.json").pipe(Effect.orDie),
    ) as { word: ReadonlyArray<{ node: { tag: number; payload: string } }> }
    expect(vector.word.length).toBe(1)
    const node = vector.word[0]!.node
    expect(node.tag).toBe(0x53)
    const payload = Buffer.from(node.payload, "hex")
    const expected = Buffer.from(CanonicalSchema.payloadOf(ConformanceVector.vectorSchema))
    expect(payload.toString("utf8")).toBe(expected.toString("utf8"))
  }).pipe(Effect.provide(layerDiskFs)))

it.effect("every registered code is admitted at the Lean-computed address", () =>
  Effect.gen(function* () {
    const committed = JSON.parse(
      yield* readFixtureString("../cas/schemas/addresses.json").pipe(Effect.orDie),
    ) as { schemas: ReadonlyArray<{ name: string; address: string }> }
    expect(committed.schemas.length).toBe(registry.length)
    for (const [name, schema] of registry) {
      const expected = committed.schemas.find((s) => s.name === name)
      expect(`${name} pinned`).toBe(
        expected === undefined ? `${name} missing from addresses.json` : `${name} pinned`,
      )
      if (expected === undefined) continue
      const id = yield* CanonicalSchema.put(schema)
      expect(`${name} ${id}`).toBe(`${name} ${expected.address}`)
    }
  }).pipe(Effect.provide(Layer.mergeAll(layerMemoryLive, layerDiskFs))))

it.effect("every registered code survives the annotation round trip", () =>
  Effect.sync(() => {
    for (const [name, schema] of registry) {
      const carried = CanonicalSchema.fromAst(schema.ast)
      expect(Option.getOrThrow(CanonicalSchema.astOf(carried))._tag)
        .toBe(schema.ast._tag)
      expect(`${name} ${Buffer.from(CanonicalSchema.payloadOf(carried)).toString("utf8")}`)
        .toBe(`${name} ${Buffer.from(CanonicalSchema.payloadOf(schema)).toString("utf8")}`)
    }
  }))
